import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import '../../../core/theme/app_theme.dart';
import 'backup_screen.dart';

class AdminScreen extends ConsumerWidget{const AdminScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final admin=ref.watch(isAdminProvider).asData?.value??false;return Scaffold(appBar:AppBar(title:const Text('Administration')),body:ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:AppColors.teal,borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ACCOUNT',style:TextStyle(color:Colors.white70,letterSpacing:1)),const SizedBox(height:6),Text(ref.watch(authRepositoryProvider).currentUser?.email??'Signed in',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800,fontSize:17)),Text(admin?'Administrator privileges':'Standard account',style:const TextStyle(color:Colors.white70))]),),const SectionTitle('Business settings'),_tile(context,'Invoice terms','Edit printed terms and conditions',Icons.description_outlined,()=>_editTerms(context,ref)),_tile(context,'Backup & restore','Export or restore Firestore business records',Icons.backup_outlined,()=>_backup(context,ref)),_tile(context,'Refresh cloud data','Reload all synchronized collections',Icons.sync,()=>ref.invalidate(billsProvider)),if(admin)_tile(context,'Reset business records','Permanently clear bills and slips',Icons.delete_forever_outlined,()=>_reset(context,ref)),const SectionTitle('Account'),_tile(context,'Sign out','Sign out of Firebase Authentication',Icons.logout,()async{await ref.read(authRepositoryProvider).signOut();}),if(!admin)const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Admin-only actions require a Firebase Authentication custom claim: admin = true.')))]));}}
Widget _tile(BuildContext c,String title,String sub,IconData icon,VoidCallback onTap)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(onTap:onTap,leading:CircleAvatar(backgroundColor:AppPalette.of(c).subtle,child:Icon(icon,color:AppPalette.of(c).accent)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(sub),trailing:const Icon(Icons.chevron_right)));
Future<void> _editTerms(BuildContext context,WidgetRef ref)async{final repo=ref.read(billingRepositoryProvider);final current=await repo.get('settings','terms_invoice');final ctrl=TextEditingController(text:'${current?['value']??'1) Rent is cycle-based (15/20/30 days as per bill).\n2) Transport/Loading/Unloading applies only in first cycle.\n3) Advance is security deposit.'}');if(!context.mounted)return;final save=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Invoice terms'),content:SizedBox(width:480,child:TextField(controller:ctrl,maxLines:9,decoration:const InputDecoration(labelText:'Terms and conditions'))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(save==true)await repo.put('settings',{'key':'terms_invoice','value':ctrl.text});ctrl.dispose();}
void _backup(BuildContext context, WidgetRef ref) {
  Navigator.push(context, MaterialPageRoute(builder: (_) => const BackupScreen()));
}
Future<void> _reset(BuildContext context,WidgetRef ref)async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Reset business records?'),content:const Text('This permanently clears bills, customers, custom bills, slips and challans.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Reset'))]));if(yes==true){for(final s in ['bills','customers','customBills','slips','challans']){for(final row in await ref.read(billingRepositoryProvider).all(s)){await ref.read(billingRepositoryProvider).delete(s,'${row[storeKeys[s]]}');}}}}
